example_solution:
let abbreviate = (input: string) : string => {
  let firstLetter = (word: string) : string =>
    word |> Js.String.charAt(0) |> Js.String.toUpperCase;

  input
  |> Js.String.splitByRe([%re "/[\\s-]/"])
  |> Js.Array.map(Belt.Option.getExn)
  |> Js.Array.map(firstLetter)
  |> Js.Array.joinWith("");
};

test_code:
open Jest;
open Expect;
open Acronym;

describe("Acronym", () => {
  test("basic", () =>
    expect(abbreviate("Portable Network Graphics")) |> toEqual("PNG")
  );
  test("lowercase words", () =>
    expect(abbreviate("Ruby on Rails")) |> toEqual("ROR")
  );
  test("punctuation", () =>
    expect(abbreviate("First In, First Out")) |> toEqual("FIFO")
  );
  test("all caps word", () =>
    expect(abbreviate("GNU Image Manipulation Program")) |> toEqual("GIMP")
  );
  test("punctuation without whitespace", () =>
    expect(abbreviate("Complementary metal-oxide semiconductor")) |> toEqual("CMOS")
  );
});
